// ═══════════════════════════════════════════════════════
// Validate ApiCode — Module Dùng Chung (Schema_API_Metadata_Patch.sql)
// Theo n8n-config.md: đọc ApiCode + isConfirm từ body
// ═══════════════════════════════════════════════════════
const body = $input.item.json.body || $input.item.json;
const headers = $('Webhook CRUD').item.json.headers || {};

const VALID_API_CODES = [
  '@tao_don_hang',      // ExecutionType: CART — cần isConfirm
  '@them_khach_hang',   // ExecutionType: QUERY — cần isConfirm
  '@xem_hoa_don',
  '@xem_don_hang',
  '@xem_doanh_so',      // Manager+
  '@cong_no_kh',
  '@cong_no_chi_tiet',
  '@danh_muc',
  '@ton_kho_list'
];

// ApiCode bắt buộc isConfirm trước khi thực thi
const CONFIRM_REQUIRED = ['@tao_don_hang', '@them_khach_hang'];

const ApiCode = (body.ApiCode || '').trim().toLowerCase();
const username = body.username || 'default';
const token = headers.authorization || body.token || 'Bearer empty';
// isConfirm: chatbot gửi kèm theo n8n-config.md Section 3
const isConfirm = parseInt(body.isConfirm || '0', 10);
const action = (body.action || 'QUERY').toUpperCase();

if (!ApiCode) {
  return [{ json: {
    loi: true,
    message: 'Thiếu ApiCode. Khối 3 chỉ xử lý nghiệp vụ cơ bản.',
    valid_codes: VALID_API_CODES
  }}];
}

if (!VALID_API_CODES.includes(ApiCode)) {
  return [{ json: {
    loi: true,
    message: `ApiCode "${ApiCode}" không thuộc Module Dùng Chung. Nếu là phân tích AI, hãy gọi hook-nghiepvu-nangcao.`,
    api_code_nhan: ApiCode,
    valid_codes: VALID_API_CODES
  }}];
}

// Kiểm tra xem có cần xác nhận không
const canGoNeedConfirm = CONFIRM_REQUIRED.includes(ApiCode) && isConfirm !== 1;

return [{ json: {
  ApiCode,
  action,
  username,
  token,
  isConfirm,
  hop_le: true,
  can_confirming: canGoNeedConfirm, // true = cần hỏi xác nhận trước
  // Tham số nghiệp vụ cơ bản
  ObjectID:     body.ObjectID     || null,
  SearchText:   body.SearchText   || null,
  FromDate:     body.FromDate     || null,
  ToDate:       body.ToDate       || null,
  TopN:         body.TopN         || null,
  StatusName:   body.StatusName   || null,
  ItemID:       body.ItemID       || null,
  ItemName:     body.ItemName     || null,
  TenKhachHang: body.TenKhachHang || null,
  SoDienThoai:  body.SoDienThoai  || null,
  Type:         body.Type         || null,
  ItemList:     body.ItemList     || null,
  EmployeeID:   body.EmployeeID   || null
}}];

// n8n-config.md Section 3: isConfirm=1 bắt buộc trước @tao_don_hang, @them_khach_hang
// Trả về form confirm để chatbot hiển thị cho user
const data = $input.item.json;

const ACTION_LABELS = {
  '@tao_don_hang':    'TẠO ĐƠN HÀNG',
  '@them_khach_hang': 'THÊM KHÁCH HÀNG MỚI'
};

const label = ACTION_LABELS[data.ApiCode] || data.ApiCode.toUpperCase();

// Tóm tắt thông tin sẽ thực hiện
let tom_tat = '';
if (data.ApiCode === '@tao_don_hang') {
  tom_tat = `Tạo đơn cho khách ${data.ObjectID || '?'} — Danh sách SP: ${data.ItemList ? JSON.stringify(data.ItemList) : 'chưa có'}`;
} else if (data.ApiCode === '@them_khach_hang') {
  tom_tat = `Tên: ${data.TenKhachHang || '?'} — SĐT: ${data.SoDienThoai || '?'}`;
}

return [{ json: {
  ket_qua: `⚠️ XÁC NHẬN ${label}\n${tom_tat}\n\nVui lòng xác nhận bằng cách gửi lại yêu cầu kèm isConfirm=1 để thực hiện.`,
  can_confirm: true,
  ApiCode: data.ApiCode,
  action: data.action
}}];

const data = $input.item.json;
return [{ json: {
  ket_qua: data.message || 'ApiCode không hợp lệ cho Module Cơ Bản.',
  loi: true,
  goi_y: 'Nếu cần phân tích AI, hãy dùng Tool_NghiepVu_NangCao'
}}];

const data = $input.item.json;

if (data.error || data.status === 'error') {
  return [{ json: {
    ket_qua: `❌ Lỗi ${data.ApiCode || ''}: ${data.message || data.error || 'Lỗi kết nối API Backend.'}`,
    loi: true
  }}];
}

const payload = data.data || data.result || data.message || data;
const ApiCode = data.ApiCode || '';
let ket_qua_text = '';

if (typeof payload === 'string') {
  ket_qua_text = payload;
} else if (Array.isArray(payload)) {
  const total = payload.length;
  ket_qua_text = `Tìm thấy ${total} kết quả (${ApiCode}):\n` +
    payload.slice(0, 20).map((item, i) => `${i+1}. ${JSON.stringify(item)}`).join('\n');
  if (total > 20) ket_qua_text += `\n... và ${total - 20} kết quả khác.`;
} else {
  ket_qua_text = JSON.stringify(payload, null, 2);
}

return [{ json: {
  ket_qua: ket_qua_text,
  ApiCode: ApiCode,
  so_ban_ghi: Array.isArray(payload) ? payload.length : null
}}];
